# content.py: wording of the overview and of the collection (notes, prose). Placeholders: {C:vol/doc} = citation as printed edition + history.state.gov URL; {Q:Qnn} = verbatim quotation from quotes.py
RUN = "Agent run r5, 2026-10-25"
COLLECTION_NAME = "Recognition after force in Latin America: what the United States asked, 1877-1979"
AUTHOR_LINE = "Agent run r5, 2026-10-25"

TITLE = "How did the United States decide whether to recognize governments that came to power by force in Latin America, and what did it ask of them before recognizing?"

BL1 = ("**1. What FRUS answers directly.** FRUS answers the first half of the question well for the years 1877 to 1950 and, more thinly, for a "
"sample of cases up to 1979. Once a government had fallen to a coup or a revolution, the Department's working test was usually not how the new rulers had come to power "
"but whether they held the country, whether the people had accepted them, and whether they would honor the state's treaties and debts; the Department's own policy paper of 1948 lists exactly those three factors "
"({C:frus1948v09/d7}). Three episodes departed from that test on purpose. Woodrow Wilson's administration made a lawful, constitutional election the price of recognition "
"(Costa Rica, 1917: {C:frus1917/d379}). The Central American treaty of 1923, which the United States said it would follow though it never signed it, kept Washington from recognizing General Martínez of El Salvador from 1931 until January 1934 "
"and was dropped as a guide in 1936 ({C:frus1932v05/d618}; {C:frus1936v05/d109}). And in the Second World War recognition of Argentina and Bolivia waited on consultation among the American republics and on their conduct toward the Axis "
"({C:frus1944v07/d231}). What the United States asked for was rarely one thing. A promise to honor international obligations appears in nearly every case; an election or a return to constitutional government was demanded in Bolivia in 1920 and Peru in 1962; "
"Mexico was asked in 1921 for a treaty protecting American-owned property ({C:frus1921v02/d344}); the Dominican Republic in 1916 was pressed to accept American financial control ({C:frus1916/d258}); Peru's military rulers in 1962 were asked for civil liberties, "
"free elections and outside observers ({C:frus1961-63v12/d423}). From 1948 the Department deliberately separated recognition from approval, and by 1979 it described its practice as recognizing nations, not governments, and simply continuing relations "
"({C:frus1977-80v15/d276}). The argument rests on fifty-six documents in 31 volumes, drawn from a wider field of about seventeen hundred documents that sit under editors' headings about recognition in 38 volumes; the exact counts are in the memo.")

BL2_INTRO = ("**2. Where FRUS points for the rest.** The printed documents are a selection. Two different channels show where the unprinted record lies, and they are not added together. "
"The first channel is the series the printed documents themselves came out of; the second is the series the editors' footnotes cite without printing.")

BL2_CAME = [
"*The State Department's central decimal file, Record Group 59.* About fifteen in sixteen of the seventeen hundred cite numbers in the State Department's central decimal file, Record Group 59 at the National Archives, "
"the Department's numbered filing system of 1910 to 1949, in which a number such as 824.00 stands for a class (the first digit; 8 is the internal affairs of a state), a country (the next two digits; 24 is Bolivia) and a subject (00 is political affairs). "
"The countries with the most such papers under recognition headings are Haiti, Bolivia, El Salvador, Costa Rica and Mexico, with dates from 1911 into 1950. The bundled reference data names this series (\"Central Decimal File 1910-1929\") but carries no National Archives identifier, entry number, or access status for it, so I cannot give them; they have to be looked up at the Archives.",
"*The older numerical file, before 1910.* Ten papers of 1907 (the Honduras section) cite numbers in the Department's numerical file, the case-numbered system used before the decimal file opened in 1910; the Archives holds it as microfilm publication M862 (series identifier 654171), and the bundled data names the reels that hold the cited cases (for example case 7357, items 1 to 215, identifiers 19794147 and 19792913), but gives no extent or access status. Papers before 1907 in the field carry no file number at all.",
"*Policy Planning Staff files, Lot 64 D 563, Record Group 59 (a lot is a batch of Department files transferred to the Archives together; Record Group 59 is the Archives' number for the State Department's records).* Kennan's December 1948 paper on Venezuela came from this lot. The National Archives divides the lot among twelve series, 1947 to 1962, entry numbers A1 558-A through A1 558-L; the one titled \"Numbered Staff Studies\" (identifier 1151288, 1947 to 1949, unrestricted) is the likeliest home of a numbered staff paper, but that is my inference, not something the data states. The \"Chronological Files\" series (identifier 1136548, entry A1 558-D, 1947 to 1962, unrestricted) is the one the data matches by control number.",
"*After 1962.* The Department's subject-numeric file (its filing scheme of 1963 to 1973, with codes such as \"POL 16\" followed by a country) for 1963, where a Dominican Republic file marked \"POL 16\" is labelled \"Independence. Recognition.\" in the 1963 schedule, its subject-numeric files of 1964 to 1973 and its Central Foreign Policy File from 1973 are named in the footnotes but have no identifier in the bundled data. Presidential-library collections cited are the Johnson Library's National Security Files (identifier 567979), the Nixon materials' NSC Files (the bundled catalog lists the Nixon Library's National Security Files, identifier 572235, which I take to be the same collection) and the Eisenhower Library's \"Project Clean Up\" records (not found in the bundled catalog). Only 11 of the 698 series in the bundled series table begin before 1940, so the first half of the story has no series-level record offline.",
]
BL2_POINTED = [
"*What the footnotes cite but do not print.* Across the seventeen hundred documents the editors' footnotes cite unprinted papers in only about one document in thirty, and every such citation is to a numbered central-file class, never to a lot file or a library collection; none is earlier than 1921. "
"The classes cited most are the political files of Nicaragua (817.00), Bolivia (824.00) and El Salvador (816.01). Over the whole of the 38 volumes, not only these documents, the editors' footnotes made about eleven hundred citations to central-file numbers, spread over some 465 classes, and a dozen citations to lot files and one library that belong to other subjects. This is a thin channel and it points back at the same decimal file, so it adds a place to look but no new series.",
]

BL3 = ("**3. What this request cannot get from FRUS.** FRUS cannot say how often the Department decided without a written record that the editors found, nor why a case the editors did not print came out as it did. "
"After 1950 the editors' own headings stop naming recognition at all, so every case after that year came from searching the text; I searched for the words recognition, junta (a ruling council of officers), coup and military, with the names of the countries, in the Western Hemisphere volumes of 1952 to 1980 that the memo lists, and read eleven cases. "
"I did not find the document that records the terms on which relations with Peru's junta resumed in August 1962: I searched the two Latin American volumes of 1961 to 1963 for resumption of relations with Peru, the query returned the Peru papers that are cited here (so it can return rows), and none of them records the act. "
"The other American governments' own reasoning is not here, only American reports of it: the Mexican doctrine of 1930 that governments should not be recognized at all but simply dealt with, and the Ecuadorian doctrine of 1907 against recognizing governments born of revolution, appear in the corpus in 28 documents in 18 volumes and in 1 document, and all are the Department's reports, not the foreign ministries' papers. "
"Two stretches are simply unsearched: 1861 to 1876, and everything after 1980. The shelf for the missing deliberations is the Department's central files (decimal file to 1963, subject-numeric file 1963 to 1973, central foreign policy file from 1973), country by country, "
"and the foreign ministries' archives, which no bundled reference data reaches. A search that finds nothing here is a statement about this selection, not about the Department's records.")

SCOPE = ("**Scope.** All 553 volumes of the series are in the copy I used; the field is the roughly seventeen hundred documents under the editors' recognition headings in 38 of them (1895 to 1950), plus fifty-six documents read from 31 volumes between 1877 and 1979. "
"I left out front matter and editorial notes, and no second edition was involved.")

DECISIONS = [
("What counts as coming to power \"by force\".", "I counted coups, revolutions and military seizures that displaced a recognized government, using the editors' headings as the net; if you also want presidents who extended their own terms or dissolved congresses (Honduras, Guatemala and Nicaragua in the 1930s), the field grows by the editors' sections on those cases and Finding 3 changes in emphasis."),
("What counts as recognition.", "I counted any act the officers themselves called recognition, resumption of relations, or continuance of relations; if you want only a formal note of recognition, the story after 1948 nearly disappears, because the Department stopped using the word."),
("Where the period starts and stops.", "I began with the first case found (Mexico, 1877) and stopped at the last volume read (1979); if you want the 1860s or the 1980s, those are unsearched and the findings may change."),
("Whether the Caribbean and Mexico belong.", "I included Haiti, the Dominican Republic, Cuba and Mexico; Haiti alone supplies more papers under recognition headings than any other country, so leaving the Caribbean out changes the counts and the 1910s findings most."),
("What counts as something \"asked\".", "I counted any requirement or assurance the documents show being sought, including through other governments or tied to aid; if you want only demands made in a formal note, the Peru, Honduras and Argentina cases of 1962 to 1966 shrink to a few lines."),
]
INCLUSION_RULE = ("Inclusion rule used meanwhile: a document is in the field if it sits under an editors' heading that names recognition, refusal or withholding of recognition, or continuance of diplomatic relations with a Latin American or Caribbean government that took power by revolution, coup or other irregular means (1895 to 1950); "
"a document is in the argument if I read it and it states the Department's test, a condition it set, or a decision and its reason (1877 to 1979).")

FINDINGS = [
# (heading, paragraph, [(quote ids with doc)])
("The test the Department inherited: control, popular assent and obligations (1877 to 1900)",
 "Long before Wilson, the Department had a rule for governments that took power by revolution. It did not judge legality; it looked for effective control, the people's acceptance, and the ability to meet international obligations. "
 "In 1877 it told its minister in Mexico that it was waiting to recognize Porfirio Díaz until it was assured that the Mexican people approved, that his government was stable, and that it would keep its treaties ({C:frus1877/d222}); in March 1878 it authorized recognition, after instalments of a claims award had been paid, the frontier had quieted, and withholding recognition had begun to hamper the talks ({C:frus1878/d344}). "
 "In 1889 recognition of the new Brazilian republic was to follow once a majority of the people had assented ({C:frus1889/d43}). By 1900 the formula was stated as a rule that recognition rests on the new rulers' de facto ability (\"de facto\" means in fact, as distinct from in law) to hold the machinery of government ({C:frus1900/d530}).",
 [("Q50","frus1877/d222"),("Q01","frus1889/d43"),("Q03","frus1900/d530")]),
("Wilson's break: legitimacy as a condition, and what it cost (1913 to 1923)",
 "In March 1913 Wilson told the Latin American missions that cooperation required government resting on law and consent ({C:frus1913/d7}), and the United States withheld recognition from General Huerta, as the Brazilian foreign minister confirmed was also his government's course ({C:frus1913/d1064}); Washington offered to recognize an administration chosen on four conditions, among them an early free election in which Huerta would not be a candidate ({C:frus1913/d1028}). "
 "In Costa Rica in 1917 the rule was spelled out: no government would be recognized unless lawfully elected under the constitution ({C:frus1917/d379}). In Bolivia in 1920 Washington and Buenos Aires agreed to wait for elections ({C:frus1920v01/d391}) and then decided to recognize the revolutionary government, as the de facto government, as soon as a provisional president was elected ({C:frus1920v01/d399}). "
 "Recognition could also be a bargaining chip: in the Dominican Republic in 1916 the United States withheld both recognition and funds until the provisional government accepted financial control and a constabulary, and ended by occupying the country ({C:frus1916/d258}); in Mexico in 1921 Charles Evans Hughes tied recognition of Obregón to a treaty guaranteeing property acquired before 1917 ({C:frus1921v02/d344}), and resumption of relations was arranged for September 1923, after a joint commission reported ({C:frus1923v02/d484}).",
 [("Q09","frus1917/d379"),("Q12","frus1920v01/d399"),("Q13","frus1921v02/d344")]),
("A treaty exception in Central America, and the return to control (1923 to 1936)",
 "In June 1923 Hughes announced that the United States would act in line with Article II of the Central American treaty, under which the signatories would not recognize a government that came to power by coup or revolution until the people's freely elected representatives had reorganized the country ({C:frus1923v02/d345}). "
 "In September 1930 Henry Stimson recognized the provisional governments of Argentina, Peru and Bolivia on the older grounds of control, a pledge to meet obligations and a promise of elections, and said he was following Jefferson's rule while treating the five Central American republics as an exception ({C:frus1930v01/d375}). "
 "The exception held for El Salvador: Stimson wrote in January 1932 that Martínez could \"under no circumstances\" be recognized ({C:frus1932v05/d618}), and in January 1934 Roosevelt approved recognizing him a day after the other Central American governments had done so, in a sequence arranged to show the United States was acting independently ({C:frus1934v05/d255}). "
 "Cuba in 1933 was judged by a test that added popular support to the ability to keep order ({C:frus1933v05/d508}). In 1936 the Department decided it would no longer be guided by the treaty and would recognize a regime that governed effectively and met its obligations even if the treaty barred it ({C:frus1936v05/d109}).",
 [("Q15","frus1923v02/d345"),("Q16","frus1930v01/d375"),("Q22","frus1936v05/d109")]),
("Recognition by consultation, and what the war added (1943 to 1945)",
 "In June 1943 Hull wanted the American governments to recognize Argentina's new regime at about the same moment, after the fullest exchange of information ({C:frus1943v05/d334}), and he welcomed it on the hope of collaboration in hemispheric solidarity ({C:frus1943v05/d340}). "
 "After the Bolivian coup of December 1943 the Department said hemisphere security and any Axis-friendly outside influence were part of the question ({C:frus1943v05/d486}) and circulated a memorandum on the junta's Nazi connections ({C:frus1944v07/d388}); "
 "Argentina's Farrell regime was refused recognition in 1944 on the ground that it would not truly join the common war effort ({C:frus1944v07/d219}; {C:frus1944v07/d231}). Ambassador Warren advised recognizing Bolivia in May 1944 because its government was sympathetic to the Allied cause and in control ({C:frus1944v07/d429}), "
 "and in June the United States offered to recognize on the same day as the others if that was the consensus ({C:frus1944v07/d437}). At the Mexico City conference of 1945 the Department hoped the Mexican doctrine of not recognizing governments at all would not be pressed ({C:frus1945v09/d70}).",
 [("Q23","frus1943v05/d334"),("Q27","frus1944v07/d231"),("Q28","frus1944v07/d429")]),
("From a weapon to a routine: relations without approval (1948 to 1959)",
 "In March 1948 the Policy Planning Staff set out the three factors the Department would weigh ({C:frus1948v09/d7}). The Bogotá conference of that year then adopted a resolution that continuing diplomatic relations implies no judgment of a government's domestic policy, and in November 1948 the Department's Office of American Republic Affairs recommended on that basis establishing relations with Peru's new junta ({C:frus1948v09/d89}). "
 "In December George Kennan advised against withholding recognition of the Venezuelan junta as a weapon ({C:frus1948v09/d115}), and a circular telegram initialed by Truman deplored the use of force while saying that non-recognition was not a suitable answer to dictatorship ({C:frus1948v09/d119}); "
 "in February 1949 a Department memorandum weighed non-recognition of Paraguay's military government as a sanction and argued that its disadvantages outweighed its advantages ({C:frus1949v02/d457}). In practice the old test of control survived ({C:frus1952-54v04/d490}), and in January 1959 John Foster Dulles recommended recognizing Castro's provisional government on its assurances and its control ({C:frus1958-60v06/d217}).",
 [("Q31","frus1948v09/d7"),("Q33","frus1948v09/d115"),("Q37","frus1958-60v06/d217")]),
("The Alliance for Progress interval, and continuity again (1962 to 1979)",
 "Kennedy's administration, which ran the Alliance for Progress aid program for Latin America, briefly turned recognition back into a lever. After the Peruvian coup of July 1962 it suspended relations ({C:frus1961-63v12/d421}), asked the junta for guarantees of civil liberties, free elections and outside observers, and said a civilian cabinet was not a sine qua non ({C:frus1961-63v12/d423}); "
 "the stated aim was to deter other coups ({C:frus1961-63v12/d427}). After the Honduran coup of October 1963 it tied recognition and aid to a return to constitutional government and sketched a constitutional route to elections ({C:frus1961-63v10-12mSupp/d160}), but in December, judging its leverage spent, it decided to recognize the Honduran and Dominican regimes ({C:frus1961-63v12/d363}). "
 "Under Johnson the practice settled into consultation and the usual assurances: in Brazil in 1964 the recognition problem was avoided by continuing relations with the president ({C:frus1964-68v31/d206}), in Argentina in 1966 the Department sought assurances on obligations and civil liberties without a fixed election date ({C:frus1964-68v31/d135}; {C:frus1964-68v31/d141}), and in Peru in 1968 other Latin American governments would not insist on an election pledge ({C:frus1964-68v31/d515}). "
 "In Chile in 1973 the junta's note was answered affirmatively within days ({C:frus1969-76v21/d358}; {C:frus1969-76v21/d360}); in Bolivia in 1978 the Department chose a posture that avoided legitimizing the coup without pushing the new rulers into a corner ({C:frus1977-80v24/d132}); and in Nicaragua in 1979 it instructed its envoy to tell the Sandinista-led junta that recognition as such did not arise ({C:frus1977-80v15/d276}).",
 [("Q39","frus1961-63v12/d423"),("Q42","frus1964-68v31/d135"),("Q48","frus1977-80v15/d276")]),
]

HOWDONE = ("I worked from a searchable copy of the whole series (553 volumes, 312,169 documents once front matter and editorial notes are set aside) and the editors' own chapter headings, which name recognition cases directly up to 1950; I turned those headings into a field of 62 sections, about seventeen hundred documents, "
"and read the source and date of each paper from the index. For the policy statements I searched the text for recognition and its companions (de facto, coup, junta, the names of the countries) and read each candidate in full or in the passages around the match, keeping the full text of all fifty-six documents on disk. "
"Because the index treats different forms of a word as the same word (\"clearing agreement\" and \"clear agreement\" match each other), I made no count of a phrase from it alone; the two phrase counts I use were each rechecked on the exact words in every document the index returned. "
"I ran a positive control (the phrase \"Department of State\", found in 552 of 553 volumes) and a negative control (a nonsense string, found nowhere) in the same pass as every scan. For the archival leads I read the bundled reference tables of National Archives series, and I stated where they hold nothing. "
"Before finishing I checked that every quotation in this overview and every excerpt in the collection is a passage I verified against its document, and that every document the overview cites is in the collection.")

